      <el-card class="form-card"><template #header><SectionHeader title="教育经历" hint="扩展默认使用第一条" :editable="editing" @edit="editing=true" @cancel="cancelEdit" @save="save" @add="startAddEducation" /></template><el-empty v-if="!form.education.length" description="尚未添加教育经历" :image-size="48"><el-button size="small" type="primary" plain @click="startAddEducation">添加教育经历</el-button></el-empty><ExperienceBlock v-for="(item,index) in form.education" :key="item.id" :title="`教育经历 ${index + 1}`" :editable="editing" :summary="[item.school, degreeLabel(item.degree), item.major].filter(Boolean).join(' · ') || '信息未填写'" @remove="removeEducation(index)"><div class="compact-grid four"><el-form-item label="学校名称" required><el-input :readonly="!editing" v-model="item.school" /></el-form-item><el-form-item label="学历"><el-select :disabled="!editing" v-model="item.degree"><el-option label="学士" value="BACHELOR" /><el-option label="硕士" value="MASTER" /><el-option label="博士" value="DOCTOR" /></el-select></el-form-item><el-form-item label="专业"><el-input :readonly="!editing" v-model="item.major" /></el-form-item><el-form-item label="学院"><el-input :readonly="!editing" v-model="item.college" /></el-form-item><el-form-item label="入学时间"><ProfileDatePicker :disabled="!editing" v-model="item.startDate" /></el-form-item><el-form-item label="毕业时间"><ProfileDatePicker :disabled="!editing" v-model="item.expectedGraduation" /></el-form-item><el-form-item label="学历形式"><el-select :disabled="!editing" v-model="item.studyMode"><el-option label="全日制" value="FULL_TIME" /><el-option label="非全日制" value="PART_TIME" /></el-select></el-form-item><el-form-item label="GPA / 排名"><el-input :readonly="!editing" v-model="item.gpa" placeholder="3.8 / 10%" /></el-form-item></div></ExperienceBlock></el-card>
      <el-card class="form-card"><template #header><SectionHeader title="实习经历" hint="支持多条，按时间倒序填写" :editable="editing" @edit="editing=true" @cancel="cancelEdit" @save="save" @add="startAddInternship" /></template><el-empty v-if="!form.work.length" description="尚未添加实习经历" :image-size="48"><el-button size="small" type="primary" plain @click="startAddInternship">添加实习经历</el-button></el-empty><ExperienceBlock v-for="(item,index) in form.work" :key="item.id" :title="item.company || `实习经历 ${index + 1}`" :editable="editing" @remove="removeInternship(index)"><div class="compact-grid four"><el-form-item label="公司名称" required><el-input :readonly="!editing" v-model="item.company" placeholder="公司" /></el-form-item><el-form-item label="实习岗位"><el-input :readonly="!editing" v-model="item.role" placeholder="岗位" /></el-form-item><el-form-item label="所属部门"><el-input :readonly="!editing" v-model="item.department" /></el-form-item><el-form-item label="工作城市"><el-input :readonly="!editing" v-model="item.city" /></el-form-item><el-form-item label="开始时间"><ProfileDatePicker :disabled="!editing" v-model="item.startDate" /></el-form-item><el-form-item label="结束时间"><ProfileDatePicker :disabled="!editing" v-model="item.endDate" /></el-form-item><el-form-item label="工作类型"><el-select :disabled="!editing" v-model="item.employmentType"><el-option label="实习" value="INTERNSHIP" /><el-option label="全职" value="FULL_TIME" /><el-option label="兼职" value="PART_TIME" /></el-select></el-form-item><el-form-item label="行业"><el-input :readonly="!editing" v-model="item.industry" /></el-form-item></div><div class="detail-grid"><el-form-item label="工作职责"><el-input :readonly="!editing" v-model="item.responsibilities" type="textarea" :rows="2" placeholder="负责的工作、协作对象与范围" /></el-form-item><el-form-item label="成果与量化"><el-input :readonly="!editing" v-model="item.achievements" type="textarea" :rows="2" placeholder="结果、指标、奖项或业务影响" /></el-form-item><el-form-item label="技术/工具"><el-input :readonly="!editing" v-model="item.technologies" placeholder="例如：Java、Spring Boot、MySQL" /></el-form-item></div></ExperienceBlock></el-card>
