      <el-card class="form-card"><template #header><SectionHeader title="荣誉与竞赛获奖" hint="奖项与竞赛成果" :editable="editing" @edit="editing=true" @cancel="cancelEdit" @save="save" @add="startAddHonor" /></template><el-empty v-if="!form.honors.length" description="尚未添加荣誉或竞赛获奖" :image-size="48"><el-button size="small" type="primary" plain @click="startAddHonor">添加荣誉</el-button></el-empty><ExperienceBlock v-for="(item,index) in form.honors" :key="item.id" :title="item.name || `荣誉 ${index + 1}`" :editable="editing" :summary="[item.level, item.date].filter(Boolean).join(' · ') || '信息未填写'" @remove="removeHonor(index)"><div class="compact-grid four"><el-form-item label="奖项名称" required><el-input :readonly="!editing" v-model="item.name" placeholder="例如：国家奖学金" /></el-form-item><el-form-item label="奖项等级"><el-input :readonly="!editing" v-model="item.level" placeholder="国家级 / 省级 / 一等奖" /></el-form-item><el-form-item label="获奖日期"><ProfileDatePicker :disabled="!editing" v-model="item.date" /></el-form-item><el-form-item label="奖项类型"><el-select :disabled="!editing" v-model="item.category"><el-option label="竞赛获奖" value="COMPETITION" /><el-option label="荣誉称号" value="HONOR" /><el-option label="奖学金" value="SCHOLARSHIP" /><el-option label="证书" value="CERTIFICATE" /></el-select></el-form-item></div><el-form-item label="奖项描述"><el-input :readonly="!editing" v-model="item.description" type="textarea" :rows="2" placeholder="主办方、参赛项目、获奖情况及个人贡献" /></el-form-item></ExperienceBlock></el-card>
    </el-form>
    <el-card class="snapshot-card"><template #header><div class="card-header"><div><span>版本快照（{{ snapshots.length }}）</span><small>恢复会生成新的修订记录</small></div><el-button text size="small" :disabled="!snapshots.length" @click="snapshotExpanded = !snapshotExpanded">{{ snapshotExpanded ? '收起' : '展开' }}</el-button></div></template><el-empty v-if="!snapshots.length" description="尚未保存档案快照" :image-size="48" /><el-table v-else v-show="snapshotExpanded" :data="snapshots" size="small"><el-table-column prop="revision" label="修订" width="90"><template #default="{ row }">v{{ row.revision }}</template></el-table-column><el-table-column prop="description" label="版本说明" min-width="280"><template #default="{ row }">{{ row.description || '未填写版本说明' }}</template></el-table-column><el-table-column label="保存时间" width="190"><template #default="{ row }">{{ formatDateTime(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="110" align="center"><template #default="{ row }"><el-button text type="primary" @click="restore(row)">恢复</el-button></template></el-table-column></el-table></el-card>
    <el-card class="pairing-card"><template #header><div class="card-header"><span>浏览器扩展</span><small>待批准 {{ pairingRequests.length }} · 已授权 {{ authorizedPairings.length }}</small></div></template><el-empty v-if="!pairingRequests.length && !authorizedPairings.length" description="暂无扩展配对记录" :image-size="48" /><div v-if="pairingRequests.length" class="pairing-section"><div class="pairing-section-title"><div><strong>待批准请求（{{ pairingRequests.length }}）</strong><small>仅批准你刚在 Chrome 中发起的请求</small></div><el-button text size="small" @click="pairingPendingExpanded = !pairingPendingExpanded">{{ pairingPendingExpanded ? '收起' : '展开' }}</el-button></div><el-table v-show="pairingPendingExpanded" :data="pairingRequests" size="small"><el-table-column prop="displayName" label="扩展" min-width="180" /><el-table-column label="请求时间" width="190"><template #default="{ row }">{{ formatDateTime(row.createdTime) }}</template></el-table-column><el-table-column label="操作" width="120" align="center"><template #default="{ row }"><el-button text type="primary" :loading="approvingId === row.id" @click="approvePairing(row)">批准</el-button></template></el-table-column></el-table></div><div v-if="authorizedPairings.length" class="pairing-section"><div class="pairing-section-title"><div><strong>已授权扩展（{{ authorizedPairings.length }}）</strong><small>同一扩展只显示一次；移除后需重新配对</small></div><el-button text size="small" @click="pairingAuthorizedExpanded = !pairingAuthorizedExpanded">{{ pairingAuthorizedExpanded ? '收起' : '展开' }}</el-button></div><el-table v-show="pairingAuthorizedExpanded" :data="authorizedPairings" size="small"><el-table-column prop="displayName" label="扩展" min-width="180" /><el-table-column label="最近授权时间" width="190"><template #default="{ row }">{{ formatDateTime(row.approvedTime) }}</template></el-table-column><el-table-column label="操作" width="120" align="center"><template #default="{ row }"><el-button text type="danger" @click="revokePairing(row)">移除授权</el-button></template></el-table-column></el-table></div></el-card>
    <el-dialog v-model="jsonImportVisible" title="从 JSON 导入个人档案" width="min(760px, 92vw)"><el-alert title="合并到已有档案会保留当前非空内容，仅补充空字段和新增经历，并创建新修订；新建独立档案会按指定名称创建可单独切换的档案，不修改现有档案。" type="info" :closable="false" show-icon /><el-form class="json-import-form" label-width="104px"><el-form-item label="导入方式"><el-radio-group v-model="jsonImportMode"><el-radio-button value="merge">合并已有档案</el-radio-button><el-radio-button value="new">新建独立档案</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="jsonImportMode === 'merge'" label="目标档案" required><el-select v-model="jsonTargetProfileId"><el-option v-for="item in profileVersions" :key="item.profileId" :label="item.defaultProfile ? `${item.name}（默认）` : item.name" :value="item.profileId" /></el-select></el-form-item><template v-else><el-form-item label="新档案名称" required><el-input v-model="jsonNewProfileName" maxlength="80" placeholder="例如：Java 后端档案" /></el-form-item><el-form-item label="版本说明"><el-input v-model="jsonNewProfileDescription" maxlength="500" placeholder="说明该档案适合的方向或来源" /></el-form-item></template><el-form-item label="档案 JSON" required><el-input v-model="jsonImportText" type="textarea" :rows="14" resize="vertical" placeholder="粘贴 AI 解析结果、格式化档案草稿，或包含 draft/content 的 JSON" /></el-form-item></el-form><template #footer><el-button @click="jsonImportVisible=false">取消</el-button><el-button type="primary" :loading="jsonImporting" @click="importProfileJson">确认导入</el-button></template></el-dialog>
    <el-dialog v-model="versionDialogVisible" :title="versionDialogMode === 'create' ? '新建个人档案版本' : '编辑版本说明'" width="560px"><el-form label-width="96px"><el-form-item label="版本名称" required><el-input v-model="versionForm.name" maxlength="80" /></el-form-item><el-form-item label="版本描述"><el-input v-model="versionForm.description" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="说明该版本突出或调整了哪些经历" /></el-form-item><el-form-item label="关联简历"><el-select v-model="versionForm.sourceResumeId" clearable filterable placeholder="可选，不限制版本用途"><el-option v-for="resume in resumes" :key="resume.id" :label="resume.fileName" :value="resume.id" /></el-select></el-form-item><el-form-item v-if="versionDialogMode === 'create'" label="复制来源"><el-select v-model="versionForm.copyFromProfileId"><el-option v-for="item in profileVersions" :key="item.profileId" :label="item.name" :value="item.profileId" /></el-select></el-form-item></el-form><template #footer><el-button @click="versionDialogVisible=false">取消</el-button><el-button type="primary" :loading="versionSaving" @click="saveVersionDialog">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { defineComponent, h, onMounted, reactive, ref } from 'vue'
import { ElButton, ElMessage, ElMessageBox } from 'element-plus'
import { candidateProfileApi, pairingApi, resumeApi } from '../api'; import http from '../api/http'; import type { CandidateProfileResponse, CandidateProfileSummary, ExtensionPairing, ProfileSnapshot, Resume } from '../types'
import ProfileDatePicker from '../components/ProfileDatePicker.vue'
type Education = Record<string,string>; type Work = Record<string,string>; type Project = Record<string,string>
const uid = (prefix: string) => `${prefix}_${crypto.randomUUID()}`
const education = (degree = ''): Education => ({ id:uid('edu'),school:'',degree,major:'',college:'',startDate:'',expectedGraduation:'',studyMode:'FULL_TIME',gpa:'' })
const internship = (): Work => ({ id:uid('work'),company:'',role:'',department:'',city:'',startDate:'',endDate:'',employmentType:'INTERNSHIP',industry:'',responsibilities:'',achievements:'',technologies:'' })
const project = (): Project => ({ id:uid('project'),name:'',role:'',startDate:'',endDate:'',type:'',teamSize:'',url:'',technologies:'',description:'',contributions:'' })
const honor = (): Record<string,string> => ({ id:uid('honor'),name:'',level:'',date:'',category:'COMPETITION',description:'' })
const SectionHeader = defineComponent({ props:{title:{type:String,required:true},hint:{type:String,required:true},editable:{type:Boolean,default:false}},emits:['add','edit','cancel','save'],setup(props,{emit}){const collapsed=ref(false);const card=(event:MouseEvent)=>(event.currentTarget as HTMLElement).closest('.el-card');const toggle=(event:MouseEvent)=>{collapsed.value=!collapsed.value;const body=card(event)?.querySelector<HTMLElement>('.el-card__body');if(body)body.style.display=collapsed.value?'none':''};return()=>h('div',{class:'card-header'},[h('div',[h('span',props.title),h('small',props.hint)]),h('div',{class:'section-actions'},[h(ElButton,{text:true,size:'small',onClick:toggle},{default:()=>collapsed.value?'展开':'收起'}),props.editable?h(ElButton,{text:true,size:'small',onClick:()=>emit('cancel')},{default:()=> '取消'}):h(ElButton,{text:true,type:'primary',size:'small',onClick:()=>emit('edit')},{default:()=> '编辑'}),props.editable&&h(ElButton,{text:true,type:'primary',size:'small',onClick:()=>emit('save')},{default:()=> '保存'}),props.editable&&h(ElButton,{text:true,type:'primary',size:'small',onClick:()=>emit('add')},{default:()=>'+ 添加'})])])} })
const ExperienceBlock = defineComponent({ props:{title:{type:String,required:true},editable:{type:Boolean,default:false}},emits:['remove'],setup(props,{emit,slots}){return()=>h('div',{class:'experience-block'},[h('div',{class:'experience-title'},[h('strong',props.title),props.editable&&h(ElButton,{text:true,type:'danger',size:'small',onClick:()=>emit('remove')},{default:()=> '删除'})]),slots.default?.()])} })
const loading=ref(false),saving=ref(false),editing=ref(false),deletingProfile=ref(false),snapshots=ref<ProfileSnapshot[]>([]),snapshotExpanded=ref(false),profileVersions=ref<CandidateProfileSummary[]>([]),selectedProfileId=ref('default'),resumes=ref<Resume[]>([]),versionDialogVisible=ref(false),versionDialogMode=ref<'create'|'edit'>('create'),versionSaving=ref(false),pairingRequests=ref<ExtensionPairing[]>([]),authorizedPairings=ref<ExtensionPairing[]>([]),pairingPendingExpanded=ref(true),pairingAuthorizedExpanded=ref(false),approvingId=ref<number>(),serviceOnline=ref(false),runtimeLabel=ref('正在识别服务类型'); const profile=ref<CandidateProfileResponse>({profileId:'default',name:'默认档案',schemaVersion:'0.1',revision:0,content:{}}); const versionForm=reactive<{name:string,description:string,sourceResumeId?:number,copyFromProfileId:string}>({name:'',description:'',copyFromProfileId:'default'}); const form=reactive({basic:{nameCn:'',gender:'UNSPECIFIED'},contact:{phone:'',email:'',currentCity:''},education:[] as Education[],work:[] as Work[],projects:[] as Project[],honors:[] as Record<string,string>[]})
const jsonImportVisible=ref(false),jsonImporting=ref(false),jsonImportMode=ref<'merge'|'new'>('merge'),jsonTargetProfileId=ref('default'),jsonNewProfileName=ref(''),jsonNewProfileDescription=ref(''),jsonImportText=ref('')
const degreeLabel=(value:string)=>({BACHELOR:'学士',MASTER:'硕士',DOCTOR:'博士'} as Record<string,string>)[value]||value
const formatDateTime=(value?:string)=>value?value.replace('T',' ').slice(0,16):'-'
const clone = <T extends Record<string,string>>(factory:()=>T,item:any):T => ({...factory(),...item})
function bind(content:Record<string,any>){Object.assign(form.basic,{nameCn:content.basic?.nameCn||'',gender:content.basic?.gender||'UNSPECIFIED'});Object.assign(form.contact,{phone:content.contact?.phone||'',email:content.contact?.email||'',currentCity:content.contact?.currentCity||''});form.education=Array.isArray(content.education)?content.education.map((x:any)=>clone(education,x)):[];form.work=Array.isArray(content.work)?content.work.map((x:any)=>clone(internship,x)):[];form.projects=Array.isArray(content.projects)?content.projects.map((x:any)=>clone(project,x)):[];form.honors=Array.isArray(content.honors)?content.honors.map((x:any)=>clone(honor,x)):[]}
async function load(){loading.value=true;try{const [versions,resumeRows]=await Promise.all([candidateProfileApi.versions(),resumeApi.list() as unknown as Promise<Resume[]>]);profileVersions.value=versions;resumes.value=resumeRows;if(!profileVersions.value.some(item=>item.profileId===selectedProfileId.value))selectedProfileId.value=profileVersions.value.find(item=>item.defaultProfile)?.profileId||profileVersions.value[0]?.profileId||'default';profile.value=await candidateProfileApi.version(selectedProfileId.value);if(!profileVersions.value.length)profileVersions.value=[{profileId:'default',name:profile.value.name||'默认档案',description:profile.value.description,sourceResumeId:profile.value.sourceResumeId,defaultProfile:true,revision:profile.value.revision,updatedAt:profile.value.updatedAt}];bind(profile.value.content);snapshots.value=await candidateProfileApi.versionSnapshots(selectedProfileId.value);pairingRequests.value=await pairingApi.pending();authorizedPairings.value=await pairingApi.authorized();editing.value=false}finally{loading.value=false}}
async function switchProfile(profileId:string){selectedProfileId.value=profileId;editing.value=false;profile.value=await candidateProfileApi.version(profileId);bind(profile.value.content);snapshots.value=await candidateProfileApi.versionSnapshots(profileId);snapshotExpanded.value=false}
function openJsonImport(){jsonImportMode.value='merge';jsonTargetProfileId.value=selectedProfileId.value;jsonNewProfileName.value='';jsonNewProfileDescription.value='';jsonImportText.value='';jsonImportVisible.value=true}
const isEmpty=(value:any)=>value===undefined||value===null||value===''||(Array.isArray(value)&&!value.length)
function fillEmpty(current:any,incoming:any):any{if(isEmpty(current))return structuredClone(incoming);if(Array.isArray(current)||Array.isArray(incoming))return current;if(current&&incoming&&typeof current==='object'&&typeof incoming==='object'){const result={...current};Object.entries(incoming).forEach(([key,value])=>{result[key]=fillEmpty(result[key],value)});return result}return current}
function mergeEntries(current:any[],incoming:any[],identityKeys:string[]){const result=current.map(item=>structuredClone(item));incoming.forEach(item=>{const match=result.find(existing=>identityKeys.some(key=>item?.[key]&&existing?.[key]===item[key]));if(match)Object.assign(match,fillEmpty(match,item));else result.push(structuredClone(item))});return result}
function normalizeImportedProfile(raw:any){const source=raw?.draft??raw?.content??raw?.profile??raw;if(!source||typeof source!=='object'||Array.isArray(source))throw new Error('JSON 中没有可识别的档案对象');return {...source,basic:source.basic&&typeof source.basic==='object'?source.basic:{},contact:source.contact&&typeof source.contact==='object'?source.contact:{},education:Array.isArray(source.education)?source.education.map((item:any)=>({...education(),...item,id:item.id||uid('edu')})):[],work:Array.isArray(source.work)?source.work.map((item:any)=>({...internship(),...item,id:item.id||uid('work')})):[],projects:Array.isArray(source.projects)?source.projects.map((item:any)=>({...project(),...item,id:item.id||uid('project')})):[],honors:Array.isArray(source.honors)?source.honors.map((item:any)=>({...honor(),...item,id:item.id||uid('honor')})):[],fieldMeta:source.fieldMeta&&typeof source.fieldMeta==='object'?source.fieldMeta:{}}}
function mergeProfileContent(current:Record<string,any>,incoming:Record<string,any>){const merged=fillEmpty(current,incoming);merged.education=mergeEntries(Array.isArray(current.education)?current.education:[],incoming.education,['school']);merged.work=mergeEntries(Array.isArray(current.work)?current.work:[],incoming.work,['company','role']);merged.projects=mergeEntries(Array.isArray(current.projects)?current.projects:[],incoming.projects,['name']);merged.honors=mergeEntries(Array.isArray(current.honors)?current.honors:[],incoming.honors,['name']);merged.fieldMeta={...(current.fieldMeta||{}),...(incoming.fieldMeta||{})};return merged}
async function importProfileJson(){if(!jsonImportText.value.trim())return ElMessage.warning('请粘贴档案 JSON');if(jsonImportMode.value==='merge'&&!jsonTargetProfileId.value)return ElMessage.warning('请选择目标档案');if(jsonImportMode.value==='new'&&!jsonNewProfileName.value.trim())return ElMessage.warning('请填写新档案名称');jsonImporting.value=true;try{let parsed:any;try{parsed=JSON.parse(jsonImportText.value)}catch(error:any){throw new Error(`JSON 格式无效：${error?.message||'请检查标点和引号'}`)}const incoming=normalizeImportedProfile(parsed);let importChanged=true;if(jsonImportMode.value==='merge'){const target=await candidateProfileApi.version(jsonTargetProfileId.value);const merged=mergeProfileContent(target.content||{},incoming);const saved=await candidateProfileApi.saveVersion(jsonTargetProfileId.value,merged);importChanged=saved.revision!==target.revision;selectedProfileId.value=jsonTargetProfileId.value}else{const created=await candidateProfileApi.createVersion({name:jsonNewProfileName.value.trim(),description:jsonNewProfileDescription.value.trim()||undefined,content:incoming});selectedProfileId.value=created.profileId}jsonImportVisible.value=false;await load();ElMessage.success(jsonImportMode.value==='merge'?(importChanged?'JSON 已合并到目标档案，并生成新修订':'档案内容没有变化，未创建新修订'):'已从 JSON 创建独立档案')}catch(error:any){ElMessage.error(error?.message||'JSON 导入失败')}finally{jsonImporting.value=false}}
function openCreateVersion(){versionDialogMode.value='create';Object.assign(versionForm,{name:'',description:'',sourceResumeId:undefined,copyFromProfileId:selectedProfileId.value});versionDialogVisible.value=true}
function openEditVersion(){versionDialogMode.value='edit';Object.assign(versionForm,{name:profile.value.name||'',description:profile.value.description||'',sourceResumeId:profile.value.sourceResumeId,copyFromProfileId:selectedProfileId.value});versionDialogVisible.value=true}
async function saveVersionDialog(){if(!versionForm.name.trim())return ElMessage.warning('请填写版本名称');versionSaving.value=true;try{if(versionDialogMode.value==='create'){const created=await candidateProfileApi.createVersion({...versionForm,name:versionForm.name.trim()});selectedProfileId.value=created.profileId}else{await candidateProfileApi.updateVersion(selectedProfileId.value,{name:versionForm.name.trim(),description:versionForm.description,sourceResumeId:versionForm.sourceResumeId})}versionDialogVisible.value=false;await load();ElMessage.success(versionDialogMode.value==='create'?'已创建档案版本':'版本说明已更新')}finally{versionSaving.value=false}}
async function deleteProfile(){if(profile.value.defaultProfile)return ElMessage.warning('默认档案不能删除');await ElMessageBox.confirm(`确定删除档案“${profile.value.name}”吗？该档案的版本快照将一并删除，已关联投递会改为未关联档案。此操作无法撤销。`,'删除个人档案',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消',confirmButtonClass:'el-button--danger'});deletingProfile.value=true;try{await candidateProfileApi.deleteVersion(selectedProfileId.value);selectedProfileId.value='default';await load();ElMessage.success('档案已删除')}finally{deletingProfile.value=false}}
const addEducation=()=>form.education.push(education()),removeEducation=(i:number)=>form.education.splice(i,1),addInternship=()=>form.work.push(internship()),removeInternship=(i:number)=>form.work.splice(i,1),addProject=()=>form.projects.push(project()),removeProject=(i:number)=>form.projects.splice(i,1)
const addHonor=()=>form.honors.push(honor()),removeHonor=(i:number)=>form.honors.splice(i,1)
function startAddEducation(){editing.value=true;addEducation()}
function startAddInternship(){editing.value=true;addInternship()}
function startAddProject(){editing.value=true;addProject()}
function startAddHonor(){editing.value=true;addHonor()}
function cancelEdit(){bind(profile.value.content);editing.value=false}
async function save(){if(form.education.some(x=>!x.school.trim())||form.work.some(x=>!x.company.trim())||form.projects.some(x=>!x.name.trim())||form.honors.some(x=>!x.name.trim()))return ElMessage.warning('已添加的经历请填写必填名称');saving.value=true;try{const previousRevision=profile.value.revision;const content={...profile.value.content,basic:{...form.basic},contact:{...form.contact},education:form.education.map(x=>({...x})),work:form.work.map(x=>({...x})),projects:form.projects.map(x=>({...x})),honors:form.honors.map(x=>({...x})),fieldMeta:profile.value.content.fieldMeta||{}};profile.value=await candidateProfileApi.saveVersion(selectedProfileId.value,content);bind(profile.value.content);snapshots.value=await candidateProfileApi.versionSnapshots(selectedProfileId.value);editing.value=false;ElMessage.success(profile.value.revision===previousRevision?'内容没有变化，未创建新修订':`档案已保存为修订 v${profile.value.revision}`)}finally{saving.value=false}}
async function restore(s:ProfileSnapshot){await ElMessageBox.confirm(`恢复 v${s.revision} 后会创建新的修订版本，是否继续？`,'恢复档案快照',{type:'warning'});profile.value=await candidateProfileApi.restoreVersion(selectedProfileId.value,s.id);bind(profile.value.content);snapshots.value=await candidateProfileApi.versionSnapshots(selectedProfileId.value);ElMessage.success(`已恢复为新修订 v${profile.value.revision}`)}
async function approvePairing(r:ExtensionPairing){await ElMessageBox.confirm(`确认批准 Chrome 扩展“${r.displayName||r.extensionId}”吗？`,'批准扩展配对',{type:'warning'});approvingId.value=r.id;try{await pairingApi.approve(r.id);pairingRequests.value=await pairingApi.pending();ElMessage.success('配对已批准，请回到 Chrome 扩展完成令牌领取。')}finally{approvingId.value=undefined}}
async function revokePairing(r:ExtensionPairing){await ElMessageBox.confirm(`移除“${r.displayName||r.extensionId}”的授权后，该扩展将不能再读取档案，是否继续？`,'移除扩展授权',{type:'warning'});await pairingApi.revoke(r.id);authorizedPairings.value=await pairingApi.authorized();ElMessage.success('已移除授权。')}
onMounted(load);onMounted(async()=>{try{const health=await http.get('/applymate/v1/health')as{runtime?:string,dataStore?:string};runtimeLabel.value=health.runtime==='DESKTOP'?'桌面端（H2）':health.runtime==='WEB'?'Web 端（MySQL）':`未知服务（${health.dataStore||'未识别数据库'}）`;serviceOnline.value=true}catch{serviceOnline.value=false}})
</script>
